import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import * as api from "../utils/api";

function UserDashboard() {
  const [account, setAccount] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const loadMyAccount = async () => {
      try {
        const data = await api.fetchMyAccount();

        console.log("My account:", data);

        setAccount(data);
      } catch (error) {
        console.error("MY ACCOUNT ERROR:", error);

        setError(api.messageFromError(error));
      } finally {
        setLoading(false);
      }
    };

    loadMyAccount();
  }, []);

  /* ================= LOADING ================= */

  if (loading) {
    return (
      <div className="dashboard-page">
        <div className="loading-card">
          <div className="loading-spinner"></div>
          <h2>Loading your account...</h2>
          <p>Please wait while we fetch your account details.</p>
        </div>
      </div>
    );
  }

  /* ================= ERROR ================= */

  if (error) {
    return (
      <div className="dashboard-page">
        <div className="error-card">
          <div className="status-icon">!</div>

          <h2>Unable to load account</h2>

          <p>{error}</p>
        </div>
      </div>
    );
  }

  /* ================= NO ACCOUNT ================= */

  if (!account) {
    return (
      <div className="dashboard-page">
        <div className="empty-state">
          <div className="empty-icon">🏦</div>

          <h2>No Account Found</h2>

          <p>
            There is no account associated with your profile.
          </p>

          <Link to="/dashboard" className="primary">
            Back to Dashboard
          </Link>
        </div>
      </div>
    );
  }

  /* ================= MAIN DASHBOARD ================= */

  return (
    <div className="dashboard-page user-dashboard">

      {/* ================= WELCOME SECTION ================= */}

      <div className="dashboard-hero">

        <div>
          <span className="dashboard-label">
            PERSONAL BANKING
          </span>

          <h1>Welcome back! 👋</h1>

          <p>
            Manage your account and transactions easily.
          </p>
        </div>

      </div>


      {/* ================= ACCOUNT CARD ================= */}

      <div className="user-account-card">

        <div className="card-top">

          <div>
            <span className="dashboard-label">
              MY ACCOUNT
            </span>

            <h2>
              {account.accountHolderName}
            </h2>

            <span className="account-number">
              Account No: {account.accountNumber}
            </span>
          </div>

          <span className="badge">
            {account.accountType}
          </span>

        </div>


        {/* ================= BALANCE ================= */}

        <div className="balance-section">

          <p className="balance-label">
            Available Balance
          </p>

          <div className="balance">
            ₹{Number(account.balance || 0).toFixed(2)}
          </div>

        </div>


        {/* ================= ACCOUNT INFORMATION ================= */}

        <div className="account-info">

          <div className="info-item">
            <span>Account Holder</span>
            <strong>
              {account.accountHolderName}
            </strong>
          </div>

          <div className="info-item">
            <span>Account Type</span>
            <strong>
              {account.accountType}
            </strong>
          </div>

          <div className="info-item">
            <span>Account Number</span>
            <strong>
              {account.accountNumber}
            </strong>
          </div>

        </div>


        {/* ================= ACTIONS ================= */}

        <h3 className="quick-actions-title">
          Quick Actions
        </h3>

        <div className="dashboard-actions">

          <Link
            to={`/accounts/${account.accountId}/deposit`}
            className="action-card"
          >
            <span className="action-icon deposit-icon">
              +
            </span>

            <span>
              <strong>Deposit</strong>
              <small>Add money to account</small>
            </span>
          </Link>


          <Link
            to={`/accounts/${account.accountId}/withdraw`}
            className="action-card"
          >
            <span className="action-icon withdraw-icon">
              ↓
            </span>

            <span>
              <strong>Withdraw</strong>
              <small>Withdraw money</small>
            </span>
          </Link>


          <Link
            to={`/accounts/${account.accountId}/transfer`}
            className="action-card"
          >
            <span className="action-icon transfer-icon">
              ⇄
            </span>

            <span>
              <strong>Transfer</strong>
              <small>Send money</small>
            </span>
          </Link>


          <Link
            to={`/accounts/${account.accountId}/transactions`}
            className="action-card"
          >
            <span className="action-icon history-icon">
              ≡
            </span>

            <span>
              <strong>Transactions</strong>
              <small>View transaction history</small>
            </span>
          </Link>

        </div>

      </div>

    </div>
  );
}

export default UserDashboard;
